#!/usr/bin/env node
/**
 * One source of truth for AI-agent configuration (see docs/ai/README.md).
 *
 * Canonical: .agents/skills/<name>/SKILL.md  (read natively by Codex, OpenCode, Antigravity)
 *            .agents/rules/<name>.md         (read natively by Antigravity)
 * Generated: .claude/skills/<name>/SKILL.md  (Claude Code adapter pointing to the canonical skill)
 *            .claude/rules/<name>.md         (Claude Code copy with `paths` frontmatter)
 *
 *   node scripts/sync-agent-config.mjs          validate + write generated files   (pnpm agents:sync)
 *   node scripts/sync-agent-config.mjs --check  validate + fail on stale files     (pnpm agents:check, CI)
 *
 * Plain files instead of symlinks so it works the same on macOS, Linux and Windows.
 */
import fs from 'node:fs'
import path from 'node:path'

const root = path.resolve(import.meta.dirname, '..')
const check = process.argv.includes('--check')
const errors = []
const rel = (p) => path.relative(root, p).split(path.sep).join('/')
const read = (p) => fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n')

// Strictest limits across the agents (Agent Skills spec, OpenCode, Antigravity, Claude Code).
const NAME_RE = /^[a-z0-9]+(-[a-z0-9]+)*$/
const MAX_NAME = 64
const MAX_DESCRIPTION = 1024
const MAX_SKILL_BYTES = 24_000 // Antigravity truncates larger files
const MAX_SKILL_LINES = 500
const MAX_ALWAYS_ON_BYTES = 24_000 // AGENTS.md / CLAUDE.md, same Antigravity limit
const SKILL_KEYS = new Set(['name', 'description', 'license', 'compatibility', 'metadata'])
const RULE_TRIGGERS = new Set(['always_on', 'model_decision', 'glob', 'manual'])

/** Minimal frontmatter reader: one `key: value` per line (all canonical files use this shape). */
function parseFrontmatter(file) {
  const text = read(file)
  const match = /^---\n([\s\S]*?)\n---\n?([\s\S]*)$/.exec(text)
  if (!match) {
    errors.push(`${rel(file)}: missing YAML frontmatter`)
    return null
  }
  const fields = {}
  const raw = {}
  for (const line of match[1].split('\n')) {
    const kv = /^([A-Za-z_-]+):\s*(.*)$/.exec(line)
    if (!kv) {
      errors.push(
        `${rel(file)}: unsupported frontmatter line "${line}" (use one key: value per line)`,
      )
      continue
    }
    raw[kv[1]] = kv[2]
    fields[kv[1]] = kv[2].replace(/^"(.*)"$/, '$1').replace(/^'(.*)'$/, '$1')
  }
  return { fields, raw, body: match[2] }
}

function generatedNote(source) {
  return `<!-- GENERATED by scripts/sync-agent-config.mjs from ${source}. Edit the source, then run \`pnpm agents:sync\`. -->`
}

const outputs = new Map() // relative path -> expected content

// ---- Skills -------------------------------------------------------------------------------
const skillsDir = path.join(root, '.agents/skills')
for (const dir of fs.readdirSync(skillsDir, { withFileTypes: true })) {
  if (!dir.isDirectory()) continue
  const file = path.join(skillsDir, dir.name, 'SKILL.md')
  if (!fs.existsSync(file)) {
    errors.push(`${rel(path.dirname(file))}: missing SKILL.md`)
    continue
  }
  const parsed = parseFrontmatter(file)
  if (!parsed) continue
  const { fields, raw, body } = parsed
  const where = rel(file)

  for (const key of Object.keys(fields)) {
    if (!SKILL_KEYS.has(key))
      errors.push(`${where}: frontmatter key "${key}" is not portable across agents`)
  }
  if (!NAME_RE.test(fields.name ?? '') || fields.name.length > MAX_NAME) {
    errors.push(`${where}: name must match ${NAME_RE} and be ≤ ${MAX_NAME} chars`)
  }
  if (fields.name !== dir.name)
    errors.push(`${where}: name "${fields.name}" must equal folder "${dir.name}"`)
  if (!fields.description || fields.description.length > MAX_DESCRIPTION) {
    errors.push(`${where}: description is required and must be ≤ ${MAX_DESCRIPTION} chars`)
  }
  if (fields.description?.includes(': ') && !/^["']/.test(raw.description)) {
    errors.push(
      `${where}: quote the description (it contains ": ", which some YAML loaders reject)`,
    )
  }
  const text = read(file)
  if (Buffer.byteLength(text) > MAX_SKILL_BYTES)
    errors.push(`${where}: larger than ${MAX_SKILL_BYTES} bytes`)
  if (text.split('\n').length > MAX_SKILL_LINES)
    errors.push(`${where}: longer than ${MAX_SKILL_LINES} lines`)
  if (!body.trim()) errors.push(`${where}: empty body`)

  outputs.set(
    `.claude/skills/${dir.name}/SKILL.md`,
    [
      '---',
      `name: ${fields.name}`,
      `description: ${raw.description}`,
      '---',
      '',
      generatedNote(where),
      '',
      `Claude Code entry point for a skill shared by every agent in this repository. Read \`${where}\` (path from the repository root) and follow it exactly; resolve the paths it mentions from the repository root.`,
      '',
    ].join('\n'),
  )
}

// ---- Scoped rules -------------------------------------------------------------------------
const rulesDir = path.join(root, '.agents/rules')
for (const entry of fs.existsSync(rulesDir) ? fs.readdirSync(rulesDir) : []) {
  if (!entry.endsWith('.md')) continue
  const file = path.join(rulesDir, entry)
  const parsed = parseFrontmatter(file)
  if (!parsed) continue
  const { fields, body } = parsed
  const where = rel(file)
  if (!RULE_TRIGGERS.has(fields.trigger)) {
    errors.push(
      `${where}: trigger must be one of ${[...RULE_TRIGGERS].join(', ')} (Antigravity drops the file otherwise)`,
    )
  }
  if (fields.trigger === 'glob' && !fields.globs)
    errors.push(`${where}: trigger "glob" requires globs`)
  if (fields.trigger === 'model_decision' && !fields.description) {
    errors.push(`${where}: trigger "model_decision" requires description`)
  }
  // Claude Code rules only understand `paths` (scoped) or no frontmatter (always loaded).
  if (fields.trigger === 'glob') {
    outputs.set(
      `.claude/rules/${entry}`,
      [
        '---',
        // Single quotes: the repo's Prettier config (singleQuote) rewrites YAML strings that way.
        `paths: '${fields.globs}'`,
        '---',
        '',
        generatedNote(where),
        '',
        body.trim(),
        '',
      ].join('\n'),
    )
  } else if (fields.trigger === 'always_on') {
    outputs.set(`.claude/rules/${entry}`, [generatedNote(where), '', body.trim(), ''].join('\n'))
  } else {
    console.log(`note: ${where} (${fields.trigger}) has no Claude Code equivalent; not generated`)
  }
}

// ---- Write or compare generated files -----------------------------------------------------
const generatedOnDisk = ['.claude/skills', '.claude/rules']
  .map((d) => path.join(root, d))
  .filter((d) => fs.existsSync(d))
  .flatMap(walk)
  .filter((p) => read(p).includes('GENERATED by scripts/sync-agent-config.mjs'))
  .map(rel)

let changed = 0
for (const [target, content] of outputs) {
  const abs = path.join(root, target)
  const current = fs.existsSync(abs) ? read(abs) : null
  if (current === content) continue
  changed++
  if (check)
    errors.push(`${target}: ${current === null ? 'missing' : 'out of date'} (run pnpm agents:sync)`)
  else {
    fs.mkdirSync(path.dirname(abs), { recursive: true })
    fs.writeFileSync(abs, content)
  }
}
for (const orphan of generatedOnDisk.filter((p) => !outputs.has(p))) {
  changed++
  if (check) errors.push(`${orphan}: generated file without a source (run pnpm agents:sync)`)
  else
    fs.rmSync(
      path.join(
        root,
        path.dirname(orphan).startsWith('.claude/skills/') ? path.dirname(orphan) : orphan,
      ),
      { recursive: true },
    )
}

// ---- Always-on instruction files and links (after writing, so generated paths exist) -----
for (const file of ['AGENTS.md', 'CLAUDE.md']) {
  const size = Buffer.byteLength(read(path.join(root, file)))
  if (size > MAX_ALWAYS_ON_BYTES)
    errors.push(`${file}: ${size} bytes; keep it under ${MAX_ALWAYS_ON_BYTES}`)
}

function walk(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((d) => {
    const p = path.join(dir, d.name)
    return d.isDirectory() ? walk(p) : d.name.endsWith('.md') ? [p] : []
  })
}
const docs = [
  path.join(root, 'AGENTS.md'),
  path.join(root, 'CLAUDE.md'),
  ...walk(path.join(root, 'docs/ai')),
  ...walk(path.join(root, '.agents')),
]
const PATH_ROOTS = /^(src|docs|e2e|scripts|\.agents|\.claude|\.github|\.storybook|public)\//
for (const file of docs) {
  const text = read(file)
  for (const [, target] of text.matchAll(/\]\(([^)\s]+)\)/g)) {
    if (/^(https?:|mailto:|#)/.test(target)) continue
    const resolved = path.resolve(path.dirname(file), target.split('#')[0])
    if (!fs.existsSync(resolved)) errors.push(`${rel(file)}: broken link ${target}`)
  }
  for (const [, ref] of text.matchAll(/`([^`\s]+)`/g)) {
    const candidate = ref.replace(/[:,.]+$/, '').replace(/:\d+$/, '')
    if (!PATH_ROOTS.test(candidate) || /[<>*{}$|]/.test(candidate)) continue
    if (!fs.existsSync(path.join(root, candidate)))
      errors.push(`${rel(file)}: path \`${candidate}\` does not exist`)
  }
}

if (errors.length) {
  console.error(
    `agent config: ${errors.length} problem(s)\n${errors.map((e) => `  - ${e}`).join('\n')}`,
  )
  process.exit(1)
}
console.log(
  `agent config OK: ${[...outputs.keys()].filter((k) => k.includes('/skills/')).length} skills, ` +
    `${[...outputs.keys()].filter((k) => k.includes('/rules/')).length} scoped rules` +
    (check ? '' : `, ${changed} generated file(s) updated`),
)
